!
! pretag.map — Tag sFlow agents by router identity
!
! Format: set_tag=N ip=ROUTER_IP
!
! Tags allow downstream consumers to identify which router
! a flow came from without parsing the agent IP themselves.
!
! Tag scheme:
!   1xxxx = spine switches
!   2xxxx = leaf switches  
!   3xxxx = border/edge routers
!

! Spine switches
set_tag=10001 ip=10.0.0.1
set_tag=10002 ip=10.0.0.2
set_tag=10003 ip=10.0.0.3
set_tag=10004 ip=10.0.0.4

! Leaf switches  
set_tag=20001 ip=10.0.1.1
set_tag=20002 ip=10.0.1.2
set_tag=20003 ip=10.0.1.3
set_tag=20004 ip=10.0.1.4

! Border routers
set_tag=30001 ip=10.0.2.1
set_tag=30002 ip=10.0.2.2
